    }
    expect(packet.reviewCycle.unchangedPassLimitations.map((x: { questionVariantId: string }) => x.questionVariantId)).toEqual([
      "question.topic.statistics.negative-predictive-value.v1", "question.topic.statistics.relative-risk-reduction.v1",
    ]);
  });

  it("retains all 28 reviewed v1 artifacts, original claims and source access dates", () => {
    expect(STATISTICS_TOPIC_REVIEWED_DEFINITIONS).toEqual(packet.reviewCycle.reviewedDefinitions);
    expect(STATISTICS_TOPIC_REVIEWED_ARTIFACTS.questions).toHaveLength(28);
    for (const [index, q] of STATISTICS_TOPIC_REVIEWED_ARTIFACTS.questions.entries()) {
      const before = packet.reviewCycle.reviewedProposals[index];
      expect(digest(q)).toBe(before.after.contentSha256);
      expect(digest(STATISTICS_TOPIC_REVIEWED_ARTIFACTS.cases[index])).toBe(before.after.caseSha256);
      expect(STATISTICS_TOPIC_REVIEWED_ARTIFACTS.timing_entries[index]).toEqual(packet.reviewCycle.reviewedArtifacts.timingEntries[index]);
    }
    expect(STATISTICS_TOPIC_REVIEWED_PREVIEW_RELEASE).toEqual(packet.reviewCycle.reviewedArtifacts.previewRelease);
    expect(STATISTICS_TOPIC_REVIEWED_CLAIMS).toHaveLength(56);
    expect(digest(STATISTICS_TOPIC_REVIEWED_CLAIMS)).toBe(ledger.reviewCorrection.reviewedClaimsSha256);
    for (const original of STATISTICS_TOPIC_REVIEWED_CLAIMS) {
      expect(ledger.claims.find((c: { id: string }) => c.id === original.id)).toEqual(original);
    }
    expect(ledger.claims).toHaveLength(66);
    for (const source of STATISTICS_TOPIC_SOURCES) {
      expect(source.accessedOn).toBe(ledger.reviewedSources.find((s: { id: string }) => s.id === source.id).accessedOn);
    }
  });

  it("versions only the five returned items without reusing old option or timing identities", () => {
    const returnedIds = new Set(independentReview.filter((r: { verdict: string }) => r.verdict !== "PASS").map((r: { id: string }) => r.id));
    expect(STATISTICS_TOPIC_REVISION_DEFINITIONS).toHaveLength(5);
    for (const status of STATISTICS_TOPIC_ITEM_STATUSES.filter(s => s.status === "revised")) {
      expect(returnedIds.has(status.reviewedQuestionVariantId)).toBe(true);
