      expect(current.conceptId).toBe(old.conceptId);
      expect(current.contentVersion).toBe("question-topic.statistics.2026-11-11.v2");
      expect(current.answerChoices.every(c => !old.answerChoices.some(o => o.id === c.id))).toBe(true);
      expect(current.supportingEvidenceClaimIds.every(id => id.includes(".r2."))).toBe(true);
      expect(status.pipelinePassed).toBe(false);
      expect(status.managerAccepted).toBe(false);
      expect(status.clinicalApproval).toBe(false);
    }
  });

  it("exposes only completely passed standalone cases in the PASS source view", () => {
    const passRelease = validateSyntheticClinicalRelease(STATISTICS_TOPIC_PASS_SOURCE_RELEASE);
    expect(passRelease.cases).toHaveLength(23);
    for (const c of passRelease.cases) {
      expect(c.decisionNodes).toHaveLength(1);
      for (const node of c.decisionNodes) {
        expect(independentReview.find((r: { id: string }) => r.id === node.questionVariantId).verdict).toBe("PASS");
        expect(STATISTICS_TOPIC_ITEM_STATUSES.find(s => s.questionVariantId === node.questionVariantId)?.status).toBe("pass-preserved");
      }
    }
    expect(STATISTICS_TOPIC_CASES.every(c => c.decisionNodes.length === 1)).toBe(true);
    expect(packet.reviewCycle.counts).toMatchObject({ passPreserved: 23, revised: 5, parked: 0, multiPartCases: 0, splitCases: 0 });
  });

  it("accounts for each clarity, cue, fairness and suggestion note without changing PASS items", () => {
    for (const row of independentReview) {
      const response = packet.reviewCycle.responses.find((r: { reviewedQuestionVariantId: string }) => r.reviewedQuestionVariantId === row.id);
      expect(response).toBeDefined();
      for (const category of ["clarityIssues", "cues", "fairness", "suggestions"]) {
        const notes = row[category] ?? [];
        expect(response.noteResponses[category]).toHaveLength(notes.length);
        response.noteResponses[category].forEach((note: { index: number; reviewNote: unknown; response: string }, index: number) => {
          expect(note.index).toBe(index);
          expect(note.reviewNote).toEqual(notes[index]);
          expect(note.response.length).toBeGreaterThan(60);
        });
      }
      expect(response.status).toBe(row.verdict === "PASS" ? "pass-preserved" : "revised");
    }
  });

  it("re-solves the raw baseline-stratum comparison and decision-changing counterfactuals", () => {
    const d = definition("stratified-confounding");
    expect(d.exhibit.kind).toBe("table");
    if (d.exhibit.kind !== "table") throw new Error("Raw table required");
    const data = d.exhibit.cells.map(row => row.map(cell => cell.split("/").map(Number) as [number, number]));
    const risks = data.map(row => row.map(([events, total]) => events / total));
    expect(risks).toEqual([[0.2, 0.2], [0.6, 0.6]]);
    expect(risks.map(row => row[0]! / row[1]!)).toEqual([1, 1]);
    const crude = [0, 1].map(column => data.reduce((sum, row) => sum + row[column]![0], 0) / data.reduce((sum, row) => sum + row[column]![1], 0));
    expect(crude).toEqual([0.56, 0.24]);
    expect(risks.map((_, column) => 0.5 * risks[0]![column]! + 0.5 * risks[1]![column]!)).toEqual([0.4, 0.4]);
    expect(d.exhibit.caption).toContain("severity recorded before pathway selection");
    expect(exhibitText(d.slug)).not.toMatch(/common cause|confound|effect modification|standardiz|risk ratio/i);
    expect(correct(d.slug)).toBe("Confounding by baseline severity");
    expect([0.4 / 0.2, 0.3 / 0.6]).toEqual([2, 0.5]); // balanced-mix modification counterfactual
    expect(d.feedback).toContain("crude/adjusted disagreement alone does not prove confounding");
  });

  it("removes the reviewed framing shortcuts while keeping single interpretation tasks", () => {
    expect(exhibitText("confidence-level")).not.toMatch(/repeat|repetition|sampling procedure/i);
    expect(definition("length-time-bias").task).toBe("Which bias is illustrated by this detection pattern?");
    expect(definition("length-time-bias").options[1]!.rationale).toContain("can coexist");
    const labels = definition("zero-correlation").options.map(o => o.label);
    expect(labels.map(words)).toEqual([7, 7, 7]);
    expect(labels.join(" ")).not.toMatch(/perfect|positive|negative/i);
    expect(labels.filter(label => label.includes("sample"))).toHaveLength(2);
    expect(labels.filter(label => label.includes("Linear"))).toHaveLength(2);
  });
});

import { createHash } from "node:crypto";
